/* DAWAH X — ahmad, অধ্যায় 44 · খণ্ড 44 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][44]=[[8601,8601,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمَّا خَلَقَ اللَّهُ عَزَّ وَجَلَّ خَلْقَهُ كَتَبَ غَلَبَتْ ‏ ‏أَوْ سَبَقَتْ ‏ ‏رَحْمَتِي غَضَبِي فَهُوَ عِنْدَهُ عَلَى الْعَرْشِ ‏","","",""],[8602,8602,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ فَأُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي يَوْمَ الْقِيَامَةِ شَفَاعَةً لِأُمَّتِي ‏","","",""],[8603,8603,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقُولُ إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ كُلِّ شَيْءٍ ‏ ‏فَالِقَ ‏ ‏الْحَبِّ وَالنَّوَى مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ ‏ ‏بِنَاصِيَتِهِ ‏ ‏أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنْ الْفَقْرِ ‏","","",""],[8604,8604,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَحَدَكُمْ ‏ ‏لَيَتَصَدَّقُ ‏ ‏بِالتَّمْرَةِ مِنْ الْكَسْبِ الطَّيِّبِ فَيَضَعُهَا فِي حَقِّهَا ‏ ‏فَيَلِيهَا ‏ ‏اللَّهُ بِيَمِينِهِ ثُمَّ مَا ‏ ‏يَبْرَحُ ‏ ‏فَيُرَبِّيهَا كَأَحْسَنِ مَا ‏ ‏يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏حَتَّى تَكُونَ مِثْلَ الْجَبَلِ أَوْ أَعْظَمَ مِنْ الْجَبَلِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏أَيْضًا ‏ ‏يَعْنِي ‏ ‏عَفَّانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏أَظُنُّهُ ‏ ‏الْوَاسِطِيَّ ‏ ‏بِإِسْنَادِهِ وَمَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَيَقْبَلُهَا اللَّهُ عَزَّ وَجَلَّ بِيَمِينِهِ ‏","","",""],[8605,8605,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ رَاكِبٌ عَلَى بَقَرَةٍ الْتَفَتَتْ إِلَيْهِ فَقَالَتْ إِنِّي لَمْ أُخْلَقْ لِهَذَا إِنَّمَا خُلِقْتُ لِلْحِرَاثَةِ قَالَ فَآمَنْتُ بِهِ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏قَالَ وَأَخَذَ الذِّئْبُ شَاةً فَتَبِعَهَا الرَّاعِي فَقَالَ الذِّئْبُ مَنْ لَهَا يَوْمَ السَّبُعِ يَوْمَ لَا رَاعِيَ لَهَا غَيْرِي قَالَ فَآمَنْتُ بِهِ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏وَمَا هُمَا يَوْمَئِذٍ فِي الْقَوْمِ ‏","","",""],[8606,8606,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8607,8607,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ ‏ ‏فَلْيُفْرِغْ ‏ ‏عَلَى يَدَيْهِ مِنْ إِنَائِهِ ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏فَقَالَ ‏ ‏قَيْسٌ الْأَشْجَعِيُّ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَكَيْفَ إِذَا جَاءَ ‏ ‏مِهْرَاسُكُمْ ‏ ‏قَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ شَرِّكَ يَا ‏ ‏قَيْسُ ‏","","",""],[8608,8608,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8609,8609,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ فَلَا تَأْتُوهَا ‏ ‏تَسْعَوْنَ ‏ ‏وَلَكِنْ امْشُوا مَشْيًا عَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا سَبَقَكُمْ فَاقْضُوا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[8610,8610,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَقِيتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَمَشَيْتُ مَعَهُ حَتَّى قَعَدَ فَانْسَلَلْتُ فَأَتَيْتُ ‏ ‏الرَّحْلَ ‏ ‏فَاغْتَسَلْتُ ثُمَّ جِئْتُ وَهُوَ قَاعِدٌ فَقَالَ أَيْنَ كُنْتَ فَقُلْتُ لَقِيتَنِي وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَكَرِهْتُ أَنْ أَجْلِسَ إِلَيْكَ وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَانْطَلَقْتُ فَاغْتَسَلْتُ قَالَ سُبْحَانَ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يَنْجُسُ ‏","","",""],[8611,8611,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ جُحَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كَسْبِ ‏ ‏الْإِمَاءِ ‏","","",""],[8612,8612,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏وَلَا ‏ ‏أُرَانِي إِلَّا قَدْ ‏ ‏سَمِعْتُهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[8613,8613,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمْسُ ‏","","",""],[8614,8614,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلَّهِ عَزَّ وَجَلَّ مَلَائِكَةً ‏ ‏سَيَّارَةً ‏ ‏فُضُلًا ‏ ‏يَبْتَغُونَ مَجَالِسَ الذِّكْرِ وَإِذَا وَجَدُوا مَجْلِسًا فِيهِ ذِكْرٌ قَعَدُوا مَعَهُمْ فَحَضَنَ بَعْضُهُمْ بَعْضًا بِأَجْنِحَتِهِمْ حَتَّى يَمْلَئُوا مَا بَيْنَهُمْ وَبَيْنَ سَمَاءِ الدُّنْيَا فَإِذَا تَفَرَّقُوا ‏ ‏عَرَجُوا ‏ ‏أَوْ صَعِدُوا ‏ ‏إِلَى السَّمَاءِ قَالَ فَيَسْأَلُهُمْ اللَّهُ عَزَّ وَجَلَّ وَهُوَ أَعْلَمُ مِنْ أَيْنَ جِئْتُمْ فَيَقُولُونَ جِئْنَاكَ مِنْ عِنْدِ عِبَادٍ لَكَ فِي الْأَرْضِ يُسَبِّحُونَكَ وَيُكَبِّرُونَكَ وَيَحْمَدُونَكَ وَيُهَلِّلُونَكَ وَيَسْأَلُونَكَ قَالَ وَمَاذَا يَسْأَلُونِي قَالُوا يَسْأَلُونَكَ جَنَّتَكَ قَالَ وَهَلْ رَأَوْا جَنَّتِي قَالُوا لَا أَيْ رَبِّ قَالَ فَكَيْفَ لَوْ قَدْ رَأَوْا جَنَّتِي قَالُوا وَيَسْتَجِيرُونَكَ قَالَ مِمَّ يَسْتَجِيرُونِي قَالُوا مِنْ نَارِكَ يَا رَبِّ قَالَ ‏ ‏وَهَلْ رَأَوْا نَارِي قَالُوا لَا قَالُوا وَيَسْتَغْفِرُونَكَ قَالَ فَيَقُولُ قَدْ غَفَرْتُ لَهُمْ وَأَعْطَيْتُهُمْ مَا سَأَلُوا ‏ ‏وَأَجَرْتُهُمْ ‏ ‏مِمَّا ‏ ‏اسْتَجَارُوا ‏ ‏قَالَ فَيَقُولُونَ رَبِّ فِيهِمْ فُلَانٌ عَبْدٌ خَطَّاءٌ إِنَّمَا مَرَّ فَجَلَسَ مَعَهُمْ قَالَ فَيَقُولُ قَدْ غَفَرْتُ لَهُمْ هُمْ الْقَوْمُ لَا يَشْقَى بِهِمْ جَلِيسُهُمْ ‏","","",""],[8615,8615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَغَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏رَجُلًا يَسْرِقُ فَقَالَ لَهُ يَا فُلَانُ أَسَرَقْتَ قَالَ لَا وَاللَّهِ مَا سَرَقْتُ قَالَ آمَنْتُ بِاللَّهِ وَكَذَّبْتُ بَصَرِي ‏","","",""],[8616,8616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا ‏ ‏شَهِدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ يُمْهِلُ حَتَّى يَذْهَبَ ثُلُثُ اللَّيْلِ ثُمَّ يَهْبِطُ فَيَقُولُ هَلْ مِنْ دَاعٍ فَيُسْتَجَابُ لَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَيُغْفَرُ لَهُ ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏وَكَانَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا بِأَحَادِيثَ عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏ثُمَّ بَلَغَنِي بَعْدُ أَنَّهُ قَالَ سَمِعْتُهَا مِنْ ‏ ‏إِسْرَائِيلَ ‏ ‏وَأَحْسَبُ هَذَا الْحَدِيثَ فِيهَا ‏","","",""],[8617,8617,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْجَبَّارِ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ يَا رَبِّ قَالَ فَيُجِيبُهَا أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏","","",""],[8618,8618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ جَالِسًا فِي الشَّمْسِ فَقَلَصَتْ عَنْهُ فَلْيَتَحَوَّلْ مِنْ مَجْلِسِهِ ‏","","",""],[8619,8619,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ الْبَصْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ صَاحِبِ ‏ ‏كَنْزٍ ‏ ‏لَا يُؤَدِّي زَكَاتَهُ إِلَّا جِيءَ بِهِ يَوْمَ الْقِيَامَةِ ‏ ‏وَبِكَنْزِهِ ‏ ‏فَيُحْمَى عَلَيْهِ صَفَائِحُ فِي نَارِ جَهَنَّمَ ‏ ‏فَيُكْوَى بِهَا جَبِينُهُ وَجَنْبُهُ وَظَهْرُهُ حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ إِبِلٍ لَا ‏ ‏يُؤَدِّي زَكَاتَهَا إِلَّا جِيءَ بِهِ يَوْمَ الْقِيَامَةِ وَبِإِبِلِهِ ‏ ‏كَأَوْفَرِ ‏ ‏مَا كَانَتْ عَلَيْهِ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏كُلَّمَا مَضَى أُخْرَاهَا ‏ ‏رُدَّ ‏ ‏عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ غَنَمٍ لَا يُؤَدِّي زَكَاتَهَا إِلَّا جِيءَ بِهِ وَبِغَنَمِهِ يَوْمَ الْقِيَامَةِ ‏ ‏كَأَوْفَرِ ‏ ‏مَا كَانَتْ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏فَتَطَؤُهُ ‏ ‏بِأَظْلَافِهَا ‏ ‏وَتَنْطَحُهُ بِقُرُونِهَا كُلَّمَا مَضَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ قِيلَ يَا رَسُولَ اللَّهِ فَالْخَيْلُ قَالَ الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ وَالْخَيْلُ ثَلَاثَةٌ وَهِيَ لِرَجُلٍ أَجْرٌ وَهِيَ لِرَجُلٍ سِتْرٌ وَهِيَ عَلَى رَجُلٍ ‏ ‏وِزْرٌ ‏ ‏فَأَمَّا الَّذِي هِيَ لَهُ أَجْرٌ الَّذِي يَتَّخِذُهَا وَيَحْبِسُهَا فِي سَبِيلِ اللَّهِ فَمَا غَيَّبَتْ فِي بُطُونِهَا فَهُوَ لَهُ أَجْرٌ وَإِنْ ‏ ‏اسْتَنَّتْ ‏ ‏مِنْهُ ‏ ‏شَرَفًا ‏ ‏أَوْ ‏ ‏شَرَفَيْنِ ‏ ‏كَانَ لَهُ فِي كُلِّ خُطْوَةٍ خَطَاهَا أَجْرٌ وَلَوْ ‏ ‏عَرَضَ ‏ ‏لَهُ نَهْرٌ فَسَقَاهَا مِنْهُ كَانَ لَهُ بِكُلِّ قَطْرَةٍ غَيَّبَتْهُ فِي بُطُونِهَا أَجْرٌ حَتَّى ذَكَرَ الْأَجْرَ فِي ‏ ‏أَرْوَاثِهَا ‏ ‏وَأَبْوَالِهَا وَأَمَّا الَّذِي هِيَ لَهُ سِتْرٌ فَرَجُلٌ يَتَّخِذُهَا تَعَفُّفًا ‏ ‏وَتَجَمُّلًا ‏ ‏وَتَكَرُّمًا وَلَا ‏ ‏يَنْسَى حَقَّهَا فِي ظُهُورِهَا وَبُطُونِهَا فِي عُسْرِهَا وَيُسْرِهَا وَأَمَّا الَّذِي هِيَ عَلَيْهِ ‏ ‏وِزْرٌ ‏ ‏فَرَجُلٌ يَتَّخِذُهَا ‏ ‏أَشَرًا ‏ ‏وَبَطَرًا ‏ ‏وَرِئَاءَ ‏ ‏النَّاسِ ‏ ‏وَبَذَخًا ‏ ‏عَلَيْهِ قِيلَ يَا رَسُولَ اللَّهِ فَالْحُمُرُ قَالَ مَا أُنْزِلَ عَلَيَّ فِيهَا شَيْءٌ إِلَّا هَذِهِ الْآيَةُ الْجَامِعَةُ ‏ ‏الْفَاذَّةُ ‏ { ‏فَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ شَرًّا يَرَهُ ‏} ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا الْكَلَامِ كُلِّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَبُو عُمَرَ الْغُدَانِيُّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏بِهَذَا الْحَدِيثِ ‏","","",""],[8620,8620,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ وَاسْمُهُ هَرِمُ بْنُ عَمْرِو بْنِ جَرِيرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَدَبَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا جِهَادٌ فِي سَبِيلِ اللَّهِ وَإِيمَانًا بِي وَتَصْدِيقًا بِرُسُلِي أَنَّهُ عَلَيَّ ضَامِنٌ أَنْ أُدْخِلَهُ الْجَنَّةَ أَوْ أُرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ ‏ ‏نَائِلًا ‏ ‏مَا ‏ ‏نَالَ ‏ ‏مِنْ أَجْرٍ أَوْ ‏ ‏غَنِيمَةٍ ‏","","",""],[8621,8621,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ ‏ ‏مَكْلُومٍ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِ اللَّهِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهِ يَوْمَ ‏ ‏كُلِمَ ‏ ‏وَكَلْمُهُ ‏ ‏يَدْمَى اللَّوْنُ لَوْنُ دَمٍ وَالرِّيحُ رِيحُ مِسْكٍ ‏","","",""],[8622,8622,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي مَا قَعَدْتُ خِلَافَ ‏ ‏سَرِيَّةٍ ‏ ‏تَغْدُو ‏ ‏فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَلَكِنْ لَا أَجِدُ مَا ‏ ‏أَحْمِلُهُمْ ‏ ‏وَلَا يَجِدُونَ سَعَةً فَيَتْبَعُونِي وَلَا تَطِيبُ أَنْفُسُهُمْ أَنْ يَتَخَلَّفُوا بَعْدِي ‏","","",""],[8623,8623,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوَدِدْتُ أَنْ أَغْزُوَ فِي سَبِيلِ اللَّهِ فَأُقْتَلَ ثُمَّ أَغْزُوَ فَأُقْتَلَ ثُمَّ أَغْزُوَ فَأُقْتَلَ ‏","","",""],[8624,8624,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ بِقَرْيَةٍ تَأْكُلُ ‏ ‏الْقُرَى ‏ ‏وَتَنْفِي ‏ ‏الْخَبَثَ ‏ ‏كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ ‏ ‏الْحَدِيدِ ‏","","",""],[8625,8625,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ مَا ‏ ‏الْغِيبَةُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قَالَ أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ أَيْ رَسُولَ اللَّهِ قَالَ إِنْ كَانَ فِي أَخِيكَ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[8626,8626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ فِي سَفَرٍ فَلَمَّا نَزَلُوا أَرْسَلُوا إِلَيْهِ وَهُوَ ‏ ‏يُصَلِّي لِيَطْعَمَ فَقَالَ لِلرُّسُلِ إِنِّي صَائِمٌ فَلَمَّا وُضِعَ الطَّعَامُ وَكَادُوا يَفْرُغُونَ جَاءَ فَجَعَلَ يَأْكُلُ فَنَظَرَ الْقَوْمُ إِلَى رَسُولِهِمْ فَقَالَ مَا تَنْظُرُونَ قَدْ أَخْبَرَنِي أَنَّهُ صَائِمٌ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏صَدَقَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَوْمُ شَهْرِ الصَّبْرِ وَثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صَوْمُ الدَّهْرِ فَقَدْ صُمْتُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَأَنَا مُفْطِرٌ فِي تَخْفِيفِ اللَّهِ وَصَائِمٌ فِي تَضْعِيفِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8627,8627,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِ ‏ ‏لُوطٍ ‏ { ‏لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَى رُكْنٍ شَدِيدٍ ‏} ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ إِلَى رَبِّهِ عَزَّ وَجَلَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا بُعِثَ بَعْدَهُ نَبِيٌّ إِلَّا فِي ثَرْوَةٍ مِنْ قَوْمِهِ ‏","","",""],[8628,8628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ رَضِيَتْ فَلَهَا رِضَاهَا وَإِنْ كَرِهَتْ فَلَا جَوَازَ عَلَيْهَا ‏ ‏يَعْنِي الْيَتِيمَةَ ‏","","",""],[8629,8629,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ يَمُوتُ يَشْهَدُ لَهُ ثَلَاثَةُ أَبْيَاتٍ مِنْ جِيرَانِهِ ‏ ‏الْأَدْنَيْنَ ‏ ‏بِخَيْرٍ إِلَّا قَالَ اللَّهُ عَزَّ وَجَلَّ قَدْ قَبِلْتُ شَهَادَةَ عِبَادِي عَلَى مَا عَلِمُوا وَغَفَرْتُ لَهُ مَا أَعْلَمُ ‏","","",""],[8630,8630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏لَأَدْفَعَنَّ ‏ ‏الرَّايَةَ ‏ ‏إِلَى رَجُلٍ يُحِبُّ اللَّهَ وَرَسُولَهُ يَفْتَحُ اللَّهُ عَلَيْهِ قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏فَمَا أَحْبَبْتُ ‏ ‏الْإِمَارَةَ ‏ ‏قَبْلَ يَوْمَئِذٍ فَتَطَاوَلْتُ لَهَا ‏ ‏وَاسْتَشْرَفْتُ ‏ ‏رَجَاءَ أَنْ يَدْفَعَهَا إِلَيَّ فَلَمَّا كَانَ الْغَدُ دَعَا ‏ ‏عَلِيًّا ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَدَفَعَهَا إِلَيْهِ فَقَالَ قَاتِلْ وَلَا تَلْتَفِتْ حَتَّى يُفْتَحَ عَلَيْكَ فَسَارَ قَرِيبًا ثُمَّ نَادَى يَا رَسُولَ اللَّهِ ‏ ‏عَلَامَ أُقَاتِلُ قَالَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا فَعَلُوا ذَلِكَ فَقَدْ مَنَعُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ ‏ ‏عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8631,8631,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُ أَصْحَابَهُ قَدْ ‏ ‏جَاءَكُمْ شَهْرُ رَمَضَانَ شَهْرٌ مُبَارَكٌ افْتَرَضَ اللَّهُ عَلَيْكُمْ صِيَامَهُ يُفْتَحُ فِيهِ أَبْوَابُ الْجَنَّةِ وَيُغْلَقُ فِيهِ أَبْوَابُ الْجَحِيمِ ‏ ‏وَتُغَلُّ ‏ ‏فِيهِ الشَّيَاطِينُ فِيهِ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ مَنْ حُرِمَ خَيْرَهَا فَقَدْ حُرِمَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏","","",""],[8632,8632,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏سَبَقَ ‏ ‏إِلَّا فِي ‏ ‏خُفٍّ ‏ ‏أَوْ ‏ ‏حَافِرٍ ‏","","",""],[8633,8633,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏رَجُلٌ يُقَالُ لَهُ ‏ ‏جُرَيْجٌ ‏ ‏كَانَ يَتَعَبَّدُ فِي ‏ ‏صَوْمَعَتِهِ ‏ ‏فَأَتَتْهُ أُمُّهُ ذَاتَ يَوْمٍ فَنَادَتْهُ فَقَالَتْ أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ بُنَيَّ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ أُكَلِّمْكَ أَنَا أُمُّكَ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ قَالَ أَيْ رَبِّ صَلَاتِي وَأُمِّي فَأَقْبَلَ عَلَى صَلَاتِهِ ثُمَّ عَادَتْ فَنَادَتْهُ مِرَارًا فَقَالَتْ أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ بُنَيَّ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ فَقَالَ أَيْ رَبِّ صَلَاتِي وَأُمِّي فَأَقْبَلَ عَلَى صَلَاتِهِ فَقَالَتْ اللَّهُمَّ لَا تُمِتْهُ حَتَّى تُرِيَهُ ‏ ‏الْمُومِسَةَ ‏ ‏وَكَانَتْ رَاعِيَةً ‏ ‏تَرْعَى غَنَمًا لِأَهْلِهَا ثُمَّ تَأْوِي إِلَى ظِلِّ ‏ ‏صَوْمَعَتِهِ ‏ ‏فَأَصَابَتْ فَاحِشَةً فَأُخِذَتْ فَحَمَلَتْ وَكَانَ مَنْ زَنَى مِنْهُمْ قُتِلَ قَالُوا مِمَّنْ قَالَتْ مِنْ ‏ ‏جُرَيْجٍ ‏ ‏صَاحِبِ ‏ ‏الصَّوْمَعَةِ ‏ ‏فَجَاءُوا بِالْفُؤُوسِ وَالْمُرُورِ فَقَالُوا أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ ‏ ‏مُرَاءٍ ‏ ‏ثُمَّ قَالُوا انْزِلْ فَأَبَى وَأَقْبَلَ عَلَى صَلَاتِهِ ‏ ‏يُصَلِّي فَأَخَذُوا فِي هَدْمِ ‏ ‏صَوْمَعَتِهِ ‏ ‏فَلَمَّا رَأَى ذَلِكَ نَزَلَ فَجَعَلُوا فِي عُنُقِهِ وَعُنُقِهَا حَبْلًا وَجَعَلُوا يَطُوفُونَ بِهِمَا فِي النَّاسِ فَوَضَعَ أُصْبُعَهُ عَلَى بَطْنِهَا فَقَالَ أَيْ غُلَامُ مَنْ أَبُوكَ قَالَ أَبِي فُلَانٌ رَاعِي الضَّأْنِ فَقَبَّلُوهُ وَقَالُوا إِنْ شِئْتَ بَنَيْنَا لَكَ ‏ ‏الصَّوْمَعَةَ ‏ ‏مِنْ ذَهَبٍ وَفِضَّةٍ قَالَ أَعِيدُوهَا كَمَا كَانَتْ ‏","","",""],[8634,8634,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ الرَّجُلُ فَوَجَدَ ‏ ‏غَرِيمُهُ ‏ ‏مَتَاعَهُ عِنْدَ الْمُفْلِسِ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[8635,8635,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ يَعْنِي الصَّائِغَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمُؤْمِنِ زَوْجَتَانِ يُرَى مُخُّ ‏ ‏سُوقِهِمَا ‏ ‏مِنْ فَوْقِ ثِيَابِهِمَا ‏","","",""],[8636,8636,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اطَّلَعَ فِي بَيْتِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَفَقَئُوا عَيْنَهُ فَلَا ‏ ‏دِيَةَ ‏ ‏لَهُ وَلَا ‏ ‏قِصَاصَ ‏","","",""],[8637,8637,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8638,8638,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَفْوَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمَدِينَةِ ‏ ‏لَتَتْرُكَنَّهَا عَلَى خَيْرِ مَا كَانَتْ مُذَلَّلَةً ‏ ‏لِلْعَوَافِي ‏ ‏يَعْنِي السِّبَاعَ وَالطَّيْرَ ‏","","",""],[8639,8639,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَرْتَقِيَنَّ جَبَّارٌ مِنْ جَبَابِرَةِ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏عَلَى مِنْبَرِي هَذَا ‏","","",""],[8640,8640,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَثَابِتٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ ‏","","",""],[8641,8641,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنْ مِنْكُمْ مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ وَفَضْلٍ وَوَضَعَ يَدَهُ عَلَى رَأْسِهِ ‏","","",""],[8642,8642,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[8643,8643,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8644,8644,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمْسُ ‏","","",""],[8645,8645,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ رَدَّهَا ‏ ‏وَصَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[8646,8646,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَعَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ وَلَا يَزْنِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَغُلُّ ‏ ‏حِينَ ‏ ‏يَغُلُّ ‏ ‏وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏حِينَ ‏ ‏يَنْتَهِبُ ‏ ‏وَهُوَ مُؤْمِنٌ ‏ ‏وَقَالَ ‏ ‏عَطَاءٌ ‏ ‏وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ شَرَفٍ وَهُوَ مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَقِيلَ لَهُ قَالَ إِنَّهُ يُنْتَزَعُ مِنْهُ الْإِيمَانُ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَطَاءٍ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ شَرَفٍ وَهُوَ مُؤْمِنٌ ‏","","",""],[8647,8647,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا نَقَصَتْ ‏ ‏صَدَقَةٌ ‏ ‏مِنْ مَالٍ وَمَا زَادَ اللَّهُ رَجُلًا بِعَفْوٍ إِلَّا عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[8648,8648,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ وَاللَّفْظِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ مَا الْغِيبَةُ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قَالَ أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ أَيْ رَسُولَ اللَّهِ قَالَ إِنْ كَانَ فِي أَخِيكَ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[8649,8649,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ رَكْعَتَيْنِ ثُمَّ سَلَّمَ قَالُوا قَصُرَتْ الصَّلَاةُ قَالَ فَقَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ بَعْدَ مَا سَلَّمَ ‏","","",""],[8650,8650,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8651,8651,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْكَعْبَةَ ‏","","",""],[8652,8652,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَاتَتْ الْمَرْأَةُ هَاجِرَةً فِرَاشَ زَوْجِهَا لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تَرْجِعَ ‏","","",""],[8653,8653,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ فِي غَيْرِ رُخْصَةٍ رَخَّصَهَا اللَّهُ لَهُ فَلَنْ يُقْبَلَ مِنْهُ الدَّهْرَ كُلَّهُ ‏","","",""],[8654,8654,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏وَقَالَ ‏ ‏أَبُو عَوَانَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ الْأَمِيرَ فَقَدْ أَطَاعَنِي وَمَنْ عَصَى الْأَمِيرَ فَقَدْ عَصَانِي وَالْأَمِيرُ ‏ ‏مِجَنٌّ ‏ ‏فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ إِذَا وَافَقَ ذَلِكَ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَكُمْ وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا ‏","","",""],[8655,8655,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ صَلَّى عَلَى جِنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا وَتَبِعَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏انْظُرْ مَا تُحَدِّثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَإِنَّك تُكْثِرُ الْحَدِيثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ بِيَدِهِ فَذَهَبَ بِهِ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَصَدَّقَتْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاللَّهِ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا كَانَ يَشْغَلُنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّفْقُ فِي الْأَسْوَاقِ مَا كَانَ يُهِمُّنِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا كَلِمَةً يُعَلِّمُنِيهَا أَوْ لُقْمَةً يَلْقُمُنِيهَا ‏","","",""],[8656,8656,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدِ بْنِ خُمَيْرٍ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِقُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعِ الْغَنَائِمِ حَتَّى تُقْسَمَ وَعَنْ بَيْعِ الثَّمَرَةِ حَتَّى ‏ ‏تُحْرَزَ ‏ ‏مِنْ كُلِّ ‏ ‏عَارِضٍ ‏ ‏وَأَنْ يُصَلِّيَ الرَّجُلُ حَتَّى ‏ ‏يَحْتَزِمَ ‏","","",""],[8657,8657,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا شَكَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْوَةَ قَلْبِهِ فَقَالَ ‏ ‏امْسَحْ رَأْسَ الْيَتِيمِ وَأَطْعِمْ الْمِسْكِينَ ‏","","",""],[8658,8658,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ مِنْ الْأَرْضِ شِبْرًا بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[8659,8659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هُنَّ أَيَّامُ ‏ ‏طُعْمٍ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏يَعْنِي ‏ ‏أَيَّامَ التَّشْرِيقِ ‏","","",""],[8660,8660,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏مَا ‏ ‏الطِّيَرَةُ ‏ ‏قَالَ لَا ‏ ‏طَائِرَ ‏ ‏ثَلَاثَ مَرَّاتِ وَقَالَ خَيْرُ الْفَأْلِ الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[8661,8661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ أَحَدُكُمْ الْإِقَامَةَ فَلْيَأْتِ عَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكَ فَلْيُصَلِّ وَمَا فَاتَهُ فَلْيُتِمَّ ‏","","",""],[8662,8662,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ الرَّاشِيَ وَالْمُرْتَشِيَ فِي الْحُكْمِ ‏","","",""],[8663,8663,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَمَنَّى أَحَدُكُمْ فَلْيَنْظُرْ مَا الَّذِي يَتَمَنَّى فَإِنَّهُ لَا يَدْرِي مَا الَّذِي يُكْتَبُ لَهُ مِنْ أُمْنِيَّتِهِ ‏","","",""],[8664,8664,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏أُحُدًا ‏ ‏هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فِيهَا كُلِّهَا فِي هَذِهِ الْأَرْبَعَةِ قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏","","",""],[8665,8665,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا مِنْ الشَّوَارِبِ وَأَعْفُوا اللِّحَى ‏","","",""],[8666,8666,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُونَ يَسْأَلُونَ حَتَّى يُقَالُ هَذَا اللَّهُ خَلَقَنَا فَمَنْ خَلَقَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَوَاللَّهِ إِنِّي لَجَالِسٌ يَوْمًا إِذْ قَالَ لِي رَجُلٌ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏هَذَا اللَّهُ خَلَقَنَا فَمَنْ خَلَقَ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَجَعَلْتُ أُصْبُعَيَّ فِي أُذُنَيَّ ثُمَّ صِحْتُ فَقُلْتُ صَدَقَ اللَّهُ وَرَسُولُهُ اللَّهُ الْوَاحِدُ ‏ ‏الصَّمَدُ ‏ ‏لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ ‏ ‏كُفُوًا ‏ ‏أَحَدٌ ‏","","",""],[8667,8667,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَغَارُ وَمِنْ غَيْرَةِ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حُرِّمَ عَلَيْهِ ‏","","",""],[8668,8668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيُوتِرْ ‏","","",""],[8669,8669,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏الْعَبْدُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً إِذَا سَرَقَ ‏ ‏فَبِعْهُ وَلَوْ ‏ ‏بِنَشٍّ ‏ ‏وَالنَّشُّ نِصْفُ الْأُوقِيَّةِ ‏","","",""],[8670,8670,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ الرَّاشِيَ وَالْمُرْتَشِيَ فِي الْحُكْمِ ‏","","",""],[8671,8671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ كُلُّهُنَّ حَقٌّ عَلَى كُلِّ مُسْلِمٍ ‏ ‏عِيَادَةُ ‏ ‏الْمَرِيضِ وَشُهُودُ الْجِنَازَةِ ‏ ‏وَتَشْمِيتُ ‏ ‏الْعَاطِسِ إِذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8672,8672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثَرُ عَذَابِ الْقَبْرِ فِي الْبَوْلِ ‏","","",""],[8673,8673,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[8674,8674,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَأَشْجَعُ ‏ ‏مَوَالِيَّ ‏ ‏لَيْسَ لَهُمْ دُونَ اللَّهِ وَلَا رَسُولِهِ ‏ ‏مَوْلًى ‏","","",""],[8675,8675,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً قَالَ زَعَمَ ذَاكَ ‏ ‏ثُمَامَةُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَالْآخَرِ دَوَاءً ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فَإِنَّ أَحَدَ جَنَاحَيْهِ ‏","","",""],[8676,8676,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏إِنْسَانًا ‏ ‏كَانَ ‏ ‏يَقُمُّ ‏ ‏الْمَسْجِدَ أَسْوَدَ مَاتَ ‏ ‏أَوْ مَاتَتْ ‏ ‏فَفَقَدَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا فَعَلَ الْإِنْسَانُ الَّذِي كَانَ ‏ ‏يَقُمُّ ‏ ‏الْمَسْجِدَ قَالَ فَقِيلَ لَهُ مَاتَ قَالَ فَهَلَّا ‏ ‏آذَنْتُمُونِي ‏ ‏بِهِ فَقَالُوا إِنَّهُ كَانَ لَيْلًا قَالَ فَدُلُّونِي عَلَى قَبْرِهَا قَالَ فَأَتَى الْقَبْرَ فَصَلَّى عَلَيْهَا ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏عِنْدَ ذَاكَ أَوْ فِي حَدِيثٍ آخَرَ ‏ ‏إِنَّ هَذِهِ الْقُبُورَ مَمْلُوءَةٌ ظُلْمَةً عَلَى أَهْلِهَا وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُنَوِّرُهَا بِصَلَاتِي عَلَيْهِمْ ‏","","",""],[8677,8677,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ غَالِبٍ اللَّيْثِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَهُ فَسَأَلَهُ فَقَالَ يَا نَبِيَّ اللَّهِ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ الْإِيمَانُ بِاللَّهِ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ فَإِنْ لَمْ أَسْتَطِعْ ذَاكَ قَالَ فَأَيُّ الرِّقَابِ أَعْظَمُ أَجْرًا قَالَ أَغْلَاهَا ثَمَنًا وَأَنْفَسُهَا عِنْدَ أَهْلِهَا قَالَ فَإِنْ لَمْ أَسْتَطِعْ قَالَ ‏ ‏فَتُعِينُ ‏ ‏ضَائِعًا أَوْ تَصْنَعُ ‏ ‏لِأَخْرَقَ ‏ ‏قَالَ فَإِنْ لَمْ أَسْتَطِعْ ذَاكَ قَالَ فَاحْبِسْ نَفْسَكَ عَنْ الشَّرِّ فَإِنَّهَا ‏ ‏صَدَقَةٌ ‏ ‏حَسَنَةٌ تَصَدَّقْتَ بِهَا عَلَى نَفْسِكَ ‏","","",""],[8678,8678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عِسْلُ بْنُ سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا طَلَعَ النَّجْمُ صَبَاحًا قَطُّ وَتَقُومُ ‏ ‏عَاهَةٌ ‏ ‏إِلَّا رُفِعَتْ عَنْهُمْ أَوْ خَفَّتْ ‏","","",""],[8679,8679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ صَوْتًا فَأَعْجَبَهُ فَقَالَ ‏ ‏قَدْ أَخَذْنَا فَالَكَ مِنْ ‏ ‏فِيكَ ‏","","",""],[8680,8680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ بُرْثُنٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ اللَّهُ الْجُمُعَةَ عَلَى مَنْ كَانَ قَبْلَنَا فَاخْتَلَفُوا وَهَدَانَا اللَّهُ لَهَا فَالنَّاسُ لَنَا فِيهَا تَبَعٌ ‏ ‏فَلِلْيَهُودِ ‏ ‏غَدٌ ‏ ‏وَلِلنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏","","",""],[8681,8681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ فَإِنَّ الشَّيْطَانَ يَفِرُّ مِنْ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ ‏ ‏الْبَقَرَةُ ‏","","",""],[8682,8682,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَكَلَّمْتَ يَوْمَ الْجُمُعَةِ فَقَدْ ‏ ‏لَغَوْتَ ‏ ‏وَأَلْغَيْتَ ‏","","",""],[8683,8683,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ شِبْرًا مِنْ الْأَرْضِ بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[8684,8684,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8685,8685,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏فِيهَا كُلِّهَا حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏هَكَذَا قَالَهَا أَبِي ‏","","",""],[8686,8686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَوُهَيْبٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[8687,8687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ فَتُحْرِقَ ثِيَابَهُ حَتَّى تَخْلُصَ إِلَيْهِ خَيْرٌ مِنْ أَنْ يَطَأَ عَلَى قَبْرِ رَجُلٍ مُسْلِمٍ ‏","","",""],[8688,8688,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفَ شَاةٍ فَمَضْمَضَ وَغَسَلَ يَدَهُ وَصَلَّى ‏","","",""],[8689,8689,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ ‏ ‏ثَوْرَ ‏ ‏أَقِطٍ ‏ ‏فَتَوَضَّأَ مِنْهُ وَصَلَّى ‏","","",""],[8690,8690,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَرُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[8691,8691,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اجْتَمَعَ قَوْمٌ فَتَفَرَّقُوا عَنْ غَيْرِ ذِكْرِ اللَّهِ إِلَّا كَأَنَّمَا تَفَرَّقُوا عَنْ جِيفَةِ حِمَارٍ وَكَانَ ذَلِكَ الْمَجْلِسُ عَلَيْهِمْ ‏ ‏حَسْرَةً ‏","","",""],[8692,8692,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُفْتَحُ أَبْوَابُ السَّمَاءِ كُلَّ يَوْمِ اثْنَيْنِ وَخَمِيسٍ فَيُغْفَرُ ذَلِكَ الْيَوْمَ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا إِلَّا امْرَأً كَانَ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏شَحْنَاءُ ‏ ‏فَيُقَالُ ‏ ‏أَنْظِرُوا ‏ ‏هَذَيْنِ حَتَّى يَصْطَلِحَا ‏","","",""],[8693,8693,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الدِّينَ بَدَأَ غَرِيبًا وَسَيَعُودُ غَرِيبًا كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ ‏","","",""],[8694,8694,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ ‏","","",""],[8695,8695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الْقَاصُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ دَاءٍ إِلَّا فِي الْحَبَّةِ السَّوْدَاءِ مِنْهُ شِفَاءٌ إِلَّا ‏ ‏السَّامُ ‏","","",""],[8696,8696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْبَخِيلِ وَالْمُتَصَدِّقِ مَثَلُ رَجُلَيْنِ عَلَيْهِمَا ‏ ‏جُبَّتَانِ ‏ ‏مِنْ حَدِيدٍ قَدْ ‏ ‏اضْطُرَّتْ ‏ ‏أَيْدِيهِمَا إِلَى ‏ ‏تَرَاقِيهِمَا ‏ ‏فَكُلَّمَا هَمَّ الْمُتَصَدِّقُ ‏ ‏بِصَدَقَةٍ ‏ ‏اتَّسَعَتْ عَلَيْهِ حَتَّى ‏ ‏تُعَفِّيَ ‏ ‏أَثَرَهُ ‏ ‏وَكُلَّمَا هَمَّ الْبَخِيلُ ‏ ‏بِصَدَقَةٍ ‏ ‏انْقَبَضَتْ عَلَيْهِ كُلُّ حَلْقَةٍ مِنْهَا إِلَى صَاحِبَتِهَا وَتَقَلَّصَتْ عَلَيْهِ قَالَ فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي يَقُولُ فَيَجْهَدُ أَنْ يُوَسِّعَهَا فَلَا تَتَّسِعُ ‏","","",""],[8697,8697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ مُحَمَّدِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏أَنَرَى رَبَّنَا عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ قَالَ هَلْ تَرَوْنَ الشَّمْسَ بِنِصْفِ النَّهَارِ لَيْسَ فِي السَّمَاءِ سَحَابَةٌ قَالُوا نَعَمْ قَالَ هَلْ تَرَوْنَ الْقَمَرَ لَيْلَةَ الْبَدْرِ لَيْسَ فِي السَّمَاءِ سَحَابَةٌ قَالُوا نَعَمْ قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَتَرَوُنَّ اللَّهَ عَزَّ وَجَلَّ وَلَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ كَمَا لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِمَا ‏","","",""],[8698,8698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَكْثَرَ عَذَابِ الْقَبْرِ مِنْ الْبَوْلِ ‏","","",""],[8699,8699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَاسْأَلْهُ مَا ‏ ‏بَالُ ‏ ‏النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ أَنَا لَأَسْرَعْتُ الْإِجَابَةَ وَمَا ابْتَغَيْتُ الْعُذْرَ ‏","","",""],[8700,8700,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏وَيَحْيَى بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لَغَنِيٍّ وَلَا لِذِي ‏ ‏مِرَّةٍ ‏ ‏سَوِيٍّ ‏","","",""],[8701,8701,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ ‏","","",""],[8702,8702,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي جِئْتُ الْبَارِحَةَ فَلَمْ يَمْنَعْنِي أَنْ أَدْخُلَ عَلَيْكَ إِلَّا أَنَّهُ كَانَ فِي الْبَيْتِ صُورَةٌ أَوْ كَلْبٌ ‏","","",""],[8703,8703,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ سِيرِينَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ وَلَا ‏ ‏يُنَجِّيهِ مِنْ النَّارِ إِلَّا بِرَحْمَةٍ مِنْ اللَّهِ وَفَضْلٍ قَالَ قَالُوا يَا رَسُولَ اللَّهِ وَلَا أَنْتَ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ يَقْبِضُهَا وَيَبْسُطُهَا ‏","","",""],[8704,8704,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ زَيْدٍ ‏ ‏عَمِّي ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَلَى بَابِ ‏ ‏الْمَدِينَةِ ‏ ‏فَمَرَّ شَابٌّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏كَأَنَّهُ مُسْتَرْخِي ‏ ‏الْإِزَارِ ‏ ‏قَالَ ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏فَجَعَلَ يَعْتَذِرُ فَقَالَ إِنَّهُ اسْتَرْخَى وَإِنَّهُ مِنْ كَتَّانٍ فَلَمَّا مَضَى قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي فِي ‏ ‏حُلَّةٍ ‏ ‏لَهُ مُعْجَبٌ بِنَفْسِهِ إِذْ خَسَفَ اللَّهُ بِهِ الْأَرْضَ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[8705,8705,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏ذَوَّادٌ أَبُو الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏هَجَّرْتُ ‏ ‏إِلَّا وَجَدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ فَصَلَّى ثُمَّ قَالَ ‏ ‏اشِكَمَتْ ‏ ‏دَرْدْ ‏ ‏قَالَ قُلْتُ لَا قَالَ ‏ ‏قُمْ فَصَلِّ فَإِنَّ فِي الصَّلَاةِ شِفَاءً ‏","","",""],[8706,8706,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدَعَنَّ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏الْمَدِينَةَ ‏ ‏وَهِيَ خَيْرُ مَا يَكُونُ ‏ ‏مُرْطِبَةٌ ‏ ‏مُونِعَةٌ ‏ ‏فَقِيلَ مَنْ يَأْكُلُهَا قَالَ الطَّيْرُ وَالسِّبَاعُ ‏","","",""],[8707,8707,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ ‏ ‏صَدَقَةُ ‏ ‏قَوْمِي وَهُمْ أَشَدُّ النَّاسِ عَلَى ‏ ‏الدَّجَّالِ ‏ ‏يَعْنِي ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا كَانَ قَوْمٌ مِنْ الْأَحْيَاءِ أَبْغَضُ إِلَيَّ مِنْهُمْ فَأَحْبَبْتُهُمْ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا ‏","","",""],[8708,8708,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعِمَّا لِلْمَمْلُوكِ إِذَا أَدَّى حَقَّ اللَّهِ وَحَقَّ ‏ ‏مَوَالِيهِ ‏ ‏قَالَ ‏ ‏كَعْبٌ ‏ ‏صَدَقَ اللَّهُ وَرَسُولُهُ لَا حِسَابَ عَلَيْهِ وَلَا عَلَى مُؤْمِنٍ ‏ ‏مُزْهِدٍ ‏","","",""],[8709,8709,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ فَإِنَّمَا أَنَا بَشَرٌ فَأَيُّمَا مُسْلِمٍ لَعَنْتُهُ أَوْ آذَيْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَقُرْبَةً ‏ ‏حَدَّثَنَاهُ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏أَنَّهُ قَالَ زَكَاةً وَرَحْمَةً ‏","","",""],[8710,8710,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏ابْنِ حُجَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيَخْتَصِمَنَّ كُلُّ شَيْءٍ يَوْمَ الْقِيَامَةِ حَتَّى الشَّاتَانِ فِيمَا انْتَطَحَتَا ‏","","",""],[8711,8711,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ ‏ ‏فِتَنًا ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا يَبِيعُ قَوْمٌ دِينَهُمْ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا قَلِيلٍ الْمُتَمَسِّكُ يَوْمَئِذٍ بِدِينِهِ كَالْقَابِضِ عَلَى الْجَمْرِ ‏ ‏أَوْ قَالَ عَلَى الشَّوْكِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ خَبَطِ الشَّوْكَةِ ‏","","",""],[8712,8712,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ ‏ ‏عَهْدًا ‏ ‏لَنْ ‏ ‏تُخْلِفَنِيهِ إِنَّمَا أَنَا بَشَرٌ فَأَيُّمَا عَبْدٍ جَلَدْتُهُ أَوْ شَتَمْتُهُ أَوْ سَبَبْتُهُ فَاجْعَلْهَا لَهُ صَلَاةً وَقُرْبَةً ‏","","",""],[8713,8713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏وَحَسَنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ ‏ ‏فِتَنًا ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا يَبِيعُ قَوْمٌ دِينَهُمْ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا قَلِيلٍ الْمُتَمَسِّكُ يَوْمَئِذٍ بِدِينِهِ كَالْقَابِضِ عَلَى الْجَمْرِ ‏ ‏أَوْ قَالَ عَلَى الشَّوْكِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ خَبَطِ الشَّوْكِ ‏","","",""],[8714,8714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُكْثِرُونَ هُمْ الْأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ بِالْمَالِ هَكَذَا وَهَكَذَا وَهَكَذَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَقَلِيلٌ مَا هُمْ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏وَأَشَارَ بَيْنَ عَيْنَيْهِ وَعَنْ يَمِينِهِ وَعَنْ يَسَارِهِ وَمِنْ خَلْفِهِ ‏","","",""],[8715,8715,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي إِنْ ظَنَّ بِي خَيْرًا فَلَهُ وَإِنْ ظَنَّ شَرًّا فَلَهُ ‏","","",""],[8716,8716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْروٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ أَرَادَ أَنْ يَخْلُقَ مِثْلَ خَلْقِي فَلْيَخْلُقْ ذَرَّةً أَوْ حَبَّةً ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَمَنْ ‏","","",""],[8717,8717,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ضَحَّى أَحَدُكُمْ فَلْيَأْكُلْ مِنْ أُضْحِيَّتِهِ ‏","","",""],[8718,8718,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ ‏ ‏مَعَادِنُ ‏ ‏خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا فِي الدِّينِ ‏","","",""],[8719,8719,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏بَيَّاعِ الْمُلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏ثُلَّةٌ ‏ ‏مِنْ الْأَوَّلِينَ وَقَلِيلٌ مِنْ الْآخِرِينَ ‏} ‏شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَنَزَلَتْ ‏ { ‏ثُلَّةٌ ‏ ‏مِنْ الْأَوَّلِينَ وَثُلَّةٌ مِنْ الْآخِرِينَ ‏} ‏فَقَالَ ‏ ‏أَنْتُمْ ثُلُثُ أَهْلِ الْجَنَّةِ بَلْ أَنْتُمْ نِصْفُ أَهْلِ الْجَنَّةِ وَتُقَاسِمُونَهُمْ النِّصْفَ الْبَاقِي ‏","","",""],[8720,8720,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏نَبِّئْنِي بِأَحَقِّ النَّاسِ مِنِّي صُحْبَةً فَقَالَ نَعَمْ وَاللَّهِ لَتُنَبَّأَنَّ قَالَ مَنْ قَالَ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أَبُوكَ ‏","","",""],[8721,8721,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَ الْحَدِيثَ قَالَ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ خَلَقَ خَلْقًا كَخَلْقِي فَلْيَخْلُقُوا مِثْلَ خَلْقِي ذَرَّةً أَوْ ذُبَابَةً أَوْ حَبَّةً ‏","","",""],[8722,8722,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَيْرٍ يَعْنِي عَبْدَ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ عَلَى الْمِنْبَرِ ‏ ‏أَشْعَرُ بَيْتٍ قَالَتْهُ ‏ ‏الْعَرَبُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏ ‏وَكَادَ ‏ ‏أُمَيَّةُ بْنُ أَبِي الصَّلْتِ ‏ ‏أَنْ يُسْلِمَ ‏","","",""],[8723,8723,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ قَالَ ‏ ‏لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُونَ حَتَّى تَحَابُّوا أَلَا أَدُلُّكُمْ عَلَى رَأْسِ ذَلِكَ ‏ ‏أَوْ مِلَاكِ ذَلِكَ ‏ ‏أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏ ‏و حَدَّثَنَاه ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏مَعْنَاهُ ‏","","",""],[8724,8724,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا ‏ ‏يَرِيهِ خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[8725,8725,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَأْتِي الْجُرْحُ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ الْمِسْكِ ‏","","",""],[8726,8726,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَهُوَ اشْتِرَاءُ الزَّرْعِ وَهُوَ فِي سُنْبُلِهِ ‏ ‏بِالْحِنْطَةِ ‏ ‏وَنَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَهُوَ شِرَاءُ الثِّمَارِ بِالتَّمْرِ ‏","","",""],[8727,8727,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8728,8728,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبْعَثُ النَّاسُ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏يُحْشَرُ النَّاسُ ‏ ‏عَلَى نِيَّاتِهِمْ ‏","","",""],[8729,8729,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا يَغْتَسِلُونَ عُرَاةً وَكَانَ نَبِيُّ اللَّهِ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِنْهُ الْحَيَاءُ وَالسِّتْرُ وَكَانَ يَسْتَتِرُ إِذَا اغْتَسَلَ فَطَعَنُوا فِيهِ بِعَوْرَةٍ قَالَ فَبَيْنَمَا نَبِيُّ اللَّهِ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَغْتَسِلُ يَوْمًا وَضَعَ ثِيَابَهُ عَلَى صَخْرَةٍ فَانْطَلَقَتْ الصَّخْرَةُ بِثِيَابِهِ فَاتَّبَعَهَا نَبِيُّ اللَّهِ ضَرْبًا بِعَصَاهُ وَهُوَ يَقُولُ ثَوْبِي يَا حَجَرُ ثَوْبِي يَا حَجَرُ حَتَّى انْتَهَى بِهِ إِلَى مَلَإٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَتَوَسَّطَهُمْ فَقَامَتْ وَأَخَذَ نَبِيُّ اللَّهِ ثِيَابَهُ فَنَظَرُوا فَإِذَا أَحْسَنُ النَّاسِ خَلْقًا وَأَعْدَلُهُمْ صُورَةً فَقَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏أَفَّاكِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَكَانَتْ بَرَاءَتُهُ الَّتِي بَرَّأَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا ‏","","",""],[8730,8730,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَأَحْسِبُهُ ذَكَرَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا هِجْرَةَ فَوْقَ ثَلَاثٍ فَمَنْ هَجَرَ أَخَاهُ فَوْقَ ثَلَاثٍ فَمَاتَ دَخَلَ النَّارَ ‏","","",""],[8731,8731,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَرْقُدَنَّ جُنُبًا حَتَّى تَتَوَضَّأَ ‏","","",""],[8732,8732,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[8733,8733,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَ ‏ ‏آدَمَ ‏ ‏مُوسَى ‏ ‏فَقَالَ أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ وَأَسْكَنَكَ جَنَّتَهُ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ ثُمَّ صَنَعْتَ مَا صَنَعْتَ فَقَالَ ‏ ‏آدَمُ ‏ ‏لِمُوسَى ‏ ‏أَنْتَ الَّذِي كَلَّمَكَ اللَّهُ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ قَالَ نَعَمْ قَالَ فَهَلْ تَجِدُهُ مَكْتُوبًا عَلَيَّ قَبْلَ أَنْ أُخْلَقَ قَالَ نَعَمْ قَالَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[8734,8734,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏دَاوُدَ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثَرُ مَا ‏ ‏يَلِجُ ‏ ‏بِهِ الْإِنْسَانُ النَّارَ الْأَجْوَفَانِ الْفَمُ وَالْفَرْجُ وَأَكْثَرُ مَا ‏ ‏يَلِجُ ‏ ‏بِهِ الْإِنْسَانُ الْجَنَّةَ تَقْوَى اللَّهِ عَزَّ وَجَلَّ وَحُسْنُ الْخُلُقِ ‏","","",""],[8735,8735,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمَسْتُورُ يَعْنِي ابْنَ أَبِي عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْمَخْزُومِيُّ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَجُلٌ وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْتَ ‏ ‏نَهَيْتَ النَّاسَ عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ قَالَ لَا وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[8736,8736,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ الْمُخْتَارِ الْأَنْصَارِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ فَيْرُوزَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو رَافِعٍ الصَّائِغُ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏ثَلَاثَةٌ حَفِظْتُهُنَّ عَنْ خَلِيلِي ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَتْرُ ‏ ‏قَبْلَ النَّوْمِ وَصَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى ‏","","",""],[8737,8737,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏مَوْلَى ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ بْنِ الْأَزْرَقِ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏ ‏أَحَدِ ‏ ‏بَنِي عَبْدِ الدَّارِ بْنِ قُصَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ جَاءَهُ نَاسٌ صَيَّادُونَ فِي الْبَحْرِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أَهْلُ ‏ ‏أَرْمَاثٍ ‏ ‏وَإِنَّا نَتَزَوَّدُ مَاءً يَسِيرًا إِنْ شَرِبْنَا مِنْهُ لَمْ يَكُنْ فِيهِ مَا نَتَوَضَّأُ بِهِ وَإِنْ تَوَضَّأْنَا ‏ ‏لَمْ يَكُنْ فِيهِ مَا نَشْرَبُ ‏ ‏أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَهُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏","","",""],[8738,8738,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ وَالْإِمَامُ يَخْطُبُ أَنْصِتْ فَقَدْ ‏ ‏لَغَوْتَ ‏","","",""],[8739,8739,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُمَجِّسَانِهِ كَمَثَلِ الْبَهِيمَةِ ‏ ‏تُنْتِجُ ‏ ‏الْبَهِيمَةَ هَلْ تَكُونُ فِيهَا ‏ ‏جَدْعَاءُ ‏","","",""],[8740,8740,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[8741,8741,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَمَمْتُمْ النَّاسَ فَخَفِّفُوا فَإِنَّ فِيهِمْ الْكَبِيرَ وَالضَّعِيفَ وَالصَّغِيرَ ‏ ‏وَقَالَ ‏ ‏فِي حَدِيثٍ آخَرَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ عَمْرِو بْنِ خِدَاشٍ ‏","","",""],[8742,8742,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏","","",""],[8743,8743,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ لِرَجُلٍ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِنٌّ ‏ ‏مِنْ الْإِبِلِ فَجَاءَهُ ‏ ‏يَتَقَاضَاهُ ‏ ‏فَطَلَبُوا لَهُ فَلَمْ يَجِدُوا إِلَّا ‏ ‏سِنًّا ‏ ‏فَوْقَ ‏ ‏سِنِّهِ ‏ ‏فَقَالَ أَعْطُوهُ فَقَالَ أَوْفَيْتَنِي ‏ ‏أَوْفَى ‏ ‏اللَّهُ لَكَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خِيَارَكُمْ أَحْسَنُكُمْ ‏ ‏قَضَاءً ‏","","",""],[8744,8744,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ ثُمَّ ‏ ‏جَهَدَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[8745,8745,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ تَجَاوَزَ لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تُكَلِّمْ بِهِ أَوْ تَعْمَلْ بِهِ ‏","","",""],[8746,8746,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ نَبْهَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَسُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[8747,8747,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَصْدَقُ كَلِمَةٍ قَالَهَا الشَّاعِرُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏ ‏وَكَادَ ‏ ‏أُمَيَّةُ بْنُ أَبِي الصَّلْتِ ‏ ‏أَنْ يُسْلِمَ ‏","","",""],[8748,8748,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ أَوْ التَّمْرَةُ وَالتَّمْرَتَانِ وَلَكِنْ الْمِسْكِينُ الَّذِي لَا يَسْأَلُ شَيْئًا وَلَا يُفْطَنُ بِمَكَانِهِ ‏ ‏فَيُعْطَى ‏","","",""],[8749,8749,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ يَدَعُ طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي فَالصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَلَخُلُوفُ ‏ ‏فِيهِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8750,8750,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ نِسَاءُ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏","","",""],[8751,8751,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَشْتُمُنِي ابْنُ ‏ ‏آدَمَ ‏ ‏وَمَا يَنْبَغِي لَهُ أَنْ يَشْتُمَنِي وَيُكَذِّبُنِي وَمَا يَنْبَغِي لَهُ أَنْ يُكَذِّبَنِي أَمَّا شَتْمُهُ إِيَّايَ قَوْلُهُ إِنَّ لِي وَلَدًا وَأَمَّا تَكْذِيبُهُ إِيَّايَ قَوْلُهُ لَنْ يُعِيدَنِي كَمَا بَدَأَنِي ‏","","",""],[8752,8752,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُبَالُ فِي الْمَاءِ الَّذِي لَا يَجْرِي ثُمَّ يُغْتَسَلُ مِنْهُ ‏","","",""],[8753,8753,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولُ أَحَدُكُمْ يَا ‏ ‏خَيْبَةَ ‏ ‏الدَّهْرِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ هُوَ الدَّهْرُ ‏","","",""],[8754,8754,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ نَبِيٌّ مِنْ الْأَنْبِيَاءِ ‏ ‏يَخُطُّ ‏ ‏فَمَنْ وَافَقَ عِلْمَهُ فَهُوَ عِلْمُهُ ‏","","",""],[8755,8755,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ فُرَافِصَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ ‏ ‏غِرٌّ ‏ ‏كَرِيمٌ وَإِنَّ الْفَاجِرَ ‏ ‏خَبٌّ ‏ ‏لَئِيمٌ ‏","","",""],[8756,8756,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا دَامَ فِي مَجْلِسِهِ يَنْتَظِرُ الصَّلَاةَ وَالْمَلَائِكَةُ يَقُولُونَ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏","","",""],[8757,8757,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا لَا يَبِيعَنَّ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تَلَقَّوْا الرُّكْبَانَ ‏ ‏بِبَيْعٍ وَأَيُّمَا امْرِئٍ ‏ ‏ابْتَاعَ ‏ ‏شَاةً فَوَجَدَهَا ‏ ‏مُصَرَّاةً ‏ ‏فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ وَلَا ‏ ‏يَسُمْ ‏ ‏أَحَدُكُمْ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبْ عَلَى خِطْبَتِهِ وَلَا تَسْأَلْ الْمَرْأَةُ طَلَاقَ أُخْتِهَا ‏ ‏لِتَكْتَفِئَ ‏ ‏مَا فِي إِنَائِهَا فَإِنَّ رِزْقَهَا عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8758,8758,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ ‏ ‏الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَنْ يَنْزِلَ حَكَمًا قِسْطًا وَإِمَامًا عَدْلًا فَيَقْتُلَ الْخِنْزِيرَ وَيَكْسِرَ الصَّلِيبَ وَتَكُونَ الدَّعْوَةُ وَاحِدَةً فَأَقْرِئُوهُ ‏ ‏أَوْ أَقْرِئْهُ ‏ ‏السَّلَامَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُحَدِّثُهُ فَيُصَدِّقُنِي فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ أَقْرِئُوهُ مِنِّي السَّلَامَ ‏","","",""],[8759,8759,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْقِلٌ يَعْنِي ابْنَ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّدَقَةُ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[8760,8760,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ طُولِ الْحَيَاةِ وَكَثْرَةِ الْمَالِ ‏","","",""],[8761,8761,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تَتَزَوَّجَ الْمَرْأَةُ عَلَى عَمَّتِهَا أَوْ عَلَى خَالَتِهَا ‏","","",""],[8762,8762,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ جَهَنَّمَ اسْتَأْذَنَتْ رَبَّهَا فَنَفَّسَهَا فِي كُلِّ عَامٍ مَرَّتَيْنِ فَشِدَّةُ الْحَرِّ مِنْ حَرِّ جَهَنَّمَ وَشِدَّةُ الْبَرْدِ مِنْ ‏ ‏زَمْهَرِيرِهَا ‏","","",""],[8763,8763,"","","‏ ‏و قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[8764,8764,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُفْرَدَ يَوْمُ الْجُمُعَةِ بِصَوْمٍ ‏","","",""],[8765,8765,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يُرَى رُعَاةُ الشَّاءِ رُءُوسَ النَّاسِ وَأَنْ يُرَى الْحُفَاةُ الْعُرَاةُ الْجُوَّعُ ‏ ‏يَتَبَارَوْنَ ‏ ‏فِي ‏ ‏الْبِنَاءِ ‏ ‏وَأَنْ تَلِدَ الْأَمَةُ ‏ ‏رَبَّهَا ‏ ‏أَوْ ‏ ‏رَبَّتَهَا ‏","","",""],[8766,8766,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا ثَلَاثَةٌ فَبُشْرَى مِنْ اللَّهِ وَحَدِيثُ النَّفْسِ وَتَخْوِيفٌ مِنْ الشَّيْطَانِ فَإِذَا رَأَى أَحَدُكُمْ رُؤْيَا تُعْجِبُهُ فَلْيَقُصَّهَا إِنْ شَاءَ وَإِذَا رَأَى شَيْئًا يَكْرَهُهُ فَلَا يَقُصَّهُ عَلَى أَحَدٍ وَلْيَقُمْ فَلْيُصَلِّ ‏","","",""],[8767,8767,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ ‏","","",""],[8768,8768,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي ‏","","",""],[8769,8769,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ أَتْبَاعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي هَذَا الشَّأْنِ كُفَّارُهُمْ أَتْبَاعٌ لِكُفَّارِهِمْ وَمُسْلِمُوهُمْ أَتْبَاعٌ لِمُسْلِمِيهِمْ ‏","","",""],[8770,8770,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى كُلِّ عُضْوٍ مِنْ أَعْضَاءِ بَنِي ‏ ‏آدَمَ ‏ ‏صَدَقَةٌ ‏","","",""],[8771,8771,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَاللَّهِ ‏ ‏لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلًا فَيَنْطَلِقَ إِلَى هَذَا الْجَبَلِ فَيَحْتَطِبَ مِنْ الْحَطَبِ وَيَبِيعَهُ وَيَسْتَغْنِيَ بِهِ عَنْ النَّاسِ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ حَرَمُوهُ ‏","","",""],[8772,8772,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ هُوَ ابْنُ عَمْرٍو الْهَجَرِيُّ ‏ ‏فِيمَا يَحْسَبُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا امْرَأَةٌ فِيمَنْ كَانَ قَبْلَكُمْ تُرْضِعُ ابْنًا لَهَا إِذْ مَرَّ بِهَا فَارِسٌ مُتَكَبِّرٌ عَلَيْهِ شَارَةٌ حَسَنَةٌ فَقَالَتْ الْمَرْأَةُ اللَّهُمَّ لَا تُمِتْ ابْنِي هَذَا حَتَّى أَرَاهُ مِثْلَ هَذَا الْفَارِسِ عَلَى مِثْلِ هَذَا الْفَرَسِ قَالَ فَتَرَكَ الصَّبِيُّ الثَّدْيَ ثُمَّ قَالَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَ هَذَا الْفَارِسِ قَالَ ثُمَّ عَادَ إِلَى الثَّدْيِ يَرْضَعُ ثُمَّ مَرُّوا بِجِيفَةٍ حَبَشِيَّةٍ ‏ ‏أَوْ زِنْجِيَّةٍ ‏ ‏تُجَرُّ فَقَالَتْ أُعِيذُ ابْنِي بِاللَّهِ أَنْ يَمُوتَ مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَتَرَكَ الثَّدْيَ وَقَالَ اللَّهُمَّ أَمِتْنِي مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَقَالَتْ أُمُّهُ يَا بُنَيَّ سَأَلْتُ رَبَّكَ أَنْ يَجْعَلَكَ مِثْلَ ذَلِكَ الْفَارِسِ فَقُلْتَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ وَسَأَلْتُ رَبَّكَ أَلَّا يُمِيتَكَ مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَسَأَلْتَ رَبَّكَ أَنْ يُمِيتَكَ مِيتَتَهَا قَالَ فَقَالَ الصَّبِيُّ إِنَّكِ دَعَوْتِ رَبَّكِ أَنْ يَجْعَلَنِي مِثْلَ رَجُلٍ مِنْ أَهْلِ النَّارِ وَإِنَّ الْحَبَشِيَّةَ ‏ ‏أَوْ الزِّنْجِيَّةَ ‏ ‏كَانَ أَهْلُهَا يَسُبُّونَهَا وَيَضْرِبُونَهَا وَيَظْلِمُونَهَا فَتَقُولُ ‏ ‏حَسْبِيَ اللَّهُ ‏ ‏حَسْبِيَ اللَّهُ ‏","","",""],[8773,8773,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَامَ أَحَدُكُمْ يَوْمًا فَنَسِيَ فَأَكَلَ وَشَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏","","",""],[8774,8774,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسُبُّوا الدَّهْرَ فَإِنَّ اللَّهَ هُوَ الدَّهْرُ ‏","","",""],[8775,8775,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفُ بْنُ أَبِي جَمِيلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ قَالَ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏عَبْدِي تَرَكَ شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ ‏ ‏ابْتِغَاءَ ‏ ‏مَرْضَاتِي وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[8776,8776,"","","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَأَرَادَ الطُّهُورَ فَلَا يَضَعَنَّ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[8777,8777,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شَرِيكٌ يَعْنِي ابْنَ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ أَوْ التَّمْرَتَانِ أَوْ اللُّقْمَةُ وَاللُّقْمَتَانِ إِنَّ الْمِسْكِينَ ‏ ‏الْمُتَعَفِّفُ ‏ ‏اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏لَا يَسْأَلُونَ النَّاسَ ‏ ‏إِلْحَافًا ‏ }","","",""],[8778,8778,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُوتِيتُ ‏ ‏جَوَامِعَ الْكَلَامِ ‏ ‏وَبَيْنَمَا أَنَا نَائِمٌ أُوتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدِي ‏","","",""],[8779,8779,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏رَجُلٌ آخِذٌ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ كُلَّمَا كَانَتْ ‏ ‏هَيْعَةٌ ‏ ‏اسْتَوَى ‏ ‏عَلَيْهِ أَلَا أُخْبِرُكُمْ بِالَّذِي يَلِيهِ قَالُوا بَلَى قَالَ الرَّجُلُ فِي ‏ ‏ثُلَّةٍ ‏ ‏مِنْ غَنَمِهِ يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ أَلَا أُخْبِرُكُمْ بِشَرِّ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالُوا بَلَى قَالَ الَّذِي يُسْأَلُ بِاللَّهِ وَلَا يُعْطِي بِهِ ‏","","",""],[8780,8780,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ وَأُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي لِيَوْمِ الْقِيَامَةِ شَفَاعَةً لِأُمَّتِي ‏","","",""],[8781,8781,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[8782,8782,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ هُرْمُزَ الْأَعْرَجَ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَأَلَ جَارَهُ أَنْ يَضَعَ خَشَبَةً فِي جِدَارِهِ فَلَا يَمْنَعْهُ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ وَاللَّهِ لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏وَأَبُو الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏مِثْلَهُ ‏","","",""],[8783,8783,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ وَالْإِمَامُ يَخْطُبُ فَقَدْ ‏ ‏لَغَوْتَ ‏","","",""],[8784,8784,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏إِنَّ ‏ ‏أَبَا عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ فَيَقُولُ قَدْ دَعَوْتُ رَبِّي فَلَمْ يَسْتَجِبْ لِي ‏","","",""],[8785,8785,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏فِي صَلَاةِ الْفَجْرِ بَعْدَ الرُّكُوعِ فَقَالَ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَالْمُسْتَضْعَفِينَ مِنْ الْمُسْلِمِينَ وَالْمُسْلِمِينَ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏فَوَافَقَهُ ‏ ‏الْقَاسِمُ ‏ ‏عَلَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ بَعْدَ الرُّكُوعِ ‏","","",""],[8786,8786,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَضْلُ صَلَاةِ الْجَمَاعَةِ عَلَى صَلَاةِ أَحَدِكُمْ وَحْدَهُ خَمْسَةٌ وَعِشْرُونَ جُزْءًا ‏","","",""],[8787,8787,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ وَالنَّهَارِ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ قَالَ فَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ قَالَ فَتَصْعَدُ مَلَائِكَةُ اللَّيْلِ وَتَثْبُتُ مَلَائِكَةُ النَّهَارِ قَالَ وَيَجْتَمِعُونَ فِي صَلَاةِ الْعَصْرِ قَالَ فَيَصْعَدُ مَلَائِكَةُ النَّهَارِ وَتَثْبُتُ مَلَائِكَةُ اللَّيْلِ قَالَ فَيَسْأَلُهُمْ رَبُّهُمْ ‏ ‏كَيْفَ تَرَكْتُمْ عِبَادِي قَالَ فَيَقُولُونَ أَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ وَتَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا قَدْ قَالَ فِيهِ ‏ ‏فَاغْفِرْ لَهُمْ يَوْمَ الدِّينِ ‏","","",""],[8788,8788,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيُحِبُّ أَحَدُكُمْ إِذَا رَجَعَ إِلَى أَهْلِهِ أَنْ يَجِدَ ثَلَاثَ ‏ ‏خَلِفَاتٍ ‏ ‏عِظَامٍ سِمَانٍ قَالَ قُلْنَا نَعَمْ قَالَ ‏ ‏فَثَلَاثُ آيَاتٍ يَقْرَأُ بِهِنَّ فِي الصَّلَاةِ خَيْرٌ لَهُ مِنْهُنَّ ‏","","",""],[8789,8789,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ خُبَيْبٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْبَرِي عَلَى حَوْضِي وَإِنَّ مَا بَيْنَ مِنْبَرِي وَبَيْنَ بَيْتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَصَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا كَأَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏وَالْمِسْوَرِ بْنِ رِفَاعَةَ بْنِ أَبِي مَالِكٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏لَمْ يَزِدْ وَلَمْ يَنْقُصْ ‏","","",""],[8790,8790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْسُورًا ‏ ‏مَوْلَى ‏ ‏قُرَيْشٍ ‏ ‏فِي حَلْقَةِ ‏ ‏سَعِيدٍ ‏ ‏يُحَدِّثُ ‏ ‏يَعْنِي ‏ ‏ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ مَرَّ بِهِ فَتًى يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَوَكَزَهُ ‏ ‏بِحَدِيدَةٍ كَانَتْ مَعَهُ ثُمَّ قَالَ أَلَمْ يَبْلُغْكَ مَا قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8791,8791,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ الضَّبِّيُّ الْأَحْوَصُ بْنُ جَوَّابٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ زُرَيْقٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أُحَدِّثُ نَفْسِي بِالْحَدِيثِ لَأَنْ أَخِرَّ مِنْ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَتَكَلَّمَ بِهِ قَالَ ذَلِكَ ‏ ‏صَرِيحُ ‏ ‏الْإِيمَانِ ‏","","",""],[8792,8792,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ زُرَيْقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏خَبَّبَ ‏ ‏خَادِمًا عَلَى أَهْلِهَا فَلَيْسَ مِنَّا وَمَنْ أَفْسَدَ امْرَأَةً عَلَى زَوْجِهَا فَلَيْسَ هُوَ مِنَّا ‏","","",""],[8793,8793,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ فِي الْمُنَافِقِ وَإِنْ صَلَّى وَإِنْ صَامَ وَزَعَمَ أَنَّهُ مُسْلِمٌ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا ‏ ‏ائْتُمِنَ خَانَ ‏","","",""],[8794,8794,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ كِتَابًا بِيَدِهِ لِنَفْسِهِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ فَوَضَعَهُ تَحْتَ عَرْشِهِ فِيهِ ‏ ‏رَحْمَتِي سَبَقَتْ غَضَبِي ‏","","",""],[8795,8795,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ دَعَا إِلَى ‏ ‏هُدًى ‏ ‏كَانَ لَهُ مِنْ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لَا يُنْقِصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنْ الْإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لَا يُنْقِصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا ‏","","",""],[8796,8796,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْبِرُ عَلَى ‏ ‏لَأْوَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏وَشِدَّتِهَا أَحَدٌ إِلَّا كُنْتُ لَهُ شَفِيعًا يَوْمَ الْقِيَامَةِ ‏ ‏أَوْ شَهِيدًا ‏","","",""],[8797,8797,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ التَّثَاؤُبَ مِنْ الشَّيْطَانِ فَإِذَا تَثَاءَبَ أَحَدُكُمْ ‏ ‏فَلْيَكْظِمْ ‏ ‏مَا اسْتَطَاعَ ‏","","",""],[8798,8798,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ كَافِرٌ وَقَاتِلُهُ فِي النَّارِ أَبَدًا ‏","","",""],[8799,8799,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ الْعُقُوبَةِ مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنْ الرَّحْمَةِ مَا ‏ ‏قَنَطَ ‏ ‏مِنْ رَحْمَتِهِ أَحَدٌ ‏","","",""],[8800,8800,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏صَفَرَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏وَلَا ‏ ‏نَوْءَ ‏","","",""]];
